    private val byId = records.associateBy { it.contentId }
    init {
        require(records.size == 327)
        require(byId.size == 327)
        require(records.count { it.authorityStatus == AdvancedAuthorityStatus.DIRECT_V1_2 } == 231)
        require(records.count { it.authorityStatus == AdvancedAuthorityStatus.SUPPLEMENTAL_V0_3_USER_APPROVED_GAP_SOURCE } == 96)
    }
    fun all(profile: RuleProfile): List<AdvancedMonsterRuntimeDescriptor> =
        if (profile == RuleProfile.OSE_ADVANCED_FANTASY) records else emptyList()
    fun lookup(profile: RuleProfile, datasetId: String, contentId: String): AdvancedMonsterRuntimeDescriptor? {
        if (profile != RuleProfile.OSE_ADVANCED_FANTASY || datasetId != DATASET_ID) return null
        return byId[contentId]
    }
    fun lookupByDisplayNameForbidden(@Suppress("UNUSED_PARAMETER") name: String): Nothing? = null
}
